def comps(g,val):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out={}
    for r in range(H):
        for c in range(W):
            if g[r][c]==val and not seen[r][c]:
                st=[(r,c)]; seen[r][c]=True; cells=[]
                while st:
                    i,j=st.pop(); cells.append((i,j))
                    for di in (-1,0,1):
                        for dj in (-1,0,1):
                            a,b=i+di,j+dj
                            if 0<=a<H and 0<=b<W and g[a][b]==val and not seen[a][b]:
                                seen[a][b]=True; st.append((a,b))
                out[(r,c)]=set(cells)
    return out
def comp_of(g,cells,val):
